package org.memphiszoo.custodial.vault;import org.json.JSONObject;final class NativeProviderPrincipal {final String owner;NativeProviderPrincipal(String o){owner=o;}boolean same(NativeProviderPrincipal p){return p!=null&&owner.equals(p.owner);}JSONObject json()throws VaultFailure{return new JSONObject().put("employee_id",owner).put("device_id","KIOSK_08").put("assignment_epoch",owner.equals("A")?1L:2L);}}
